// src/screens/HomeScreen.js - главный экран приложения
import React, { useState, useEffect } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  ActivityIndicator,
  Alert,
  Image 
} from 'react-native';
import useStorage from '../hooks/useStorage';
import useApi from '../hooks/useApi';
import { apiService } from '../services/apiService';
import { Ionicons } from '@expo/vector-icons';

const API_URL = 'https://fastly.picsum.photos/id/943/400/400.jpg?hmac=8l4nDrOa88qvm-XB44SzKQ3opJvRaK2c6mvvf233MLw'; 

const HomeScreen = ({ navigation }) => {
  // 🚀 Читаем настройки для определения темы
  const { value: appSettings } = useStorage('appSettings', { darkMode: false });
  const isDarkMode = appSettings?.darkMode ?? false;

  const { value: count, setValue: setCount, loading: storageLoading } = useStorage('counter', 0);
  const { data: images, loading: apiLoading, error: apiError, refetch } = useApi(API_URL);

  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  const increment = () => setCount(count + 1);
  const reset = () => setCount(0);

  const addLocalItem = () => {
    const newItem = {
      id: Date.now(),
      title: `Элемент ${localData.length + 1}`,
      timestamp: new Date().toLocaleTimeString()
    };
    setLocalData(prev => [newItem, ...prev]);
  };

  const renderImage = (image) => (
    <View key={image.id} style={styles.apiItem}>
      <Image 
        source={{ uri: image.download_url }} 
        style={styles.apiImage} 
        resizeMode="cover"
      />
      <Text style={[styles.apiName, { color: isDarkMode ? '#eee' : '#1c1c1e' }]}>Author: {image.author}</Text>
      <Text style={styles.apiEmail}>ID: {image.id}</Text>
    </View>
  );

  const createPost = async () => {
    setPostLoading(true);
    try {
      const newPost = { title: 'Новый пост', body: 'Это тестовый пост', userId: 1 };
      await new Promise(resolve => setTimeout(resolve, 500)); 
      const result = await apiService.createPost(newPost);
      Alert.alert('Успех', `POST-запрос отправлен. ID нового поста: ${result.id}`);
    } catch (e) {
      Alert.alert('Ошибка', `Не удалось отправить POST-запрос: ${e.message}.`);
    } finally {
      setPostLoading(false);
    }
  };

  const renderLocalItem = (item) => (
    <View key={item.id} style={[styles.localItem, { borderBottomColor: isDarkMode ? '#444' : '#f0f0f0' }]}>
      <Ionicons name="bookmark-outline" size={16} color={isDarkMode ? '#88c' : '#007AFF'} />
      <Text style={[styles.localText, { color: isDarkMode ? '#eee' : '#333' }]}>{item.title}</Text>
      <Text style={styles.localTimestamp}>{item.timestamp}</Text>
    </View>
  );

  const NavigationButton = ({ screen, title, icon, color }) => (
    <TouchableOpacity
      style={[styles.navButton, { backgroundColor: color }]}
      onPress={() => navigation.navigate(screen)}
    >
      <Ionicons name={icon} size={20} color="white" style={{ marginBottom: 5 }} />
      <Text style={styles.navButtonText}>{title}</Text>
    </TouchableOpacity>
  );

  const themeStyles = getStyles(isDarkMode);

  return (
    <ScrollView style={themeStyles.container}>

      {/* Секция Счетчика */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Локальный счетчик (AsyncStorage)</Text>
        {storageLoading ? (
            <ActivityIndicator size="small" color={isDarkMode ? '#88c' : '#007AFF'} />
        ) : (
            <Text style={themeStyles.counter}>Текущее значение: {count}</Text>
        )}
        <View style={styles.buttonRow}>
          <TouchableOpacity style={styles.button} onPress={increment}>
            <Text style={styles.navButtonText}>+1</Text>
          </TouchableOpacity>
          <TouchableOpacity style={[styles.button, styles.resetButton]} onPress={reset}>
            <Text style={styles.navButtonText}>Сбросить</Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* Секция API-данных */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Внешние API-Данные (Картинки)</Text>

        <TouchableOpacity 
          style={[styles.button, styles.apiButton]} 
          onPress={refetch}
          disabled={apiLoading}
        >
          <Text style={styles.navButtonText}>
            {apiLoading ? 'Загрузка...' : 'Обновить API-картинки (GET)'}
          </Text>
        </TouchableOpacity>

        <TouchableOpacity 
          style={[styles.button, styles.postButton, { opacity: postLoading ? 0.6 : 1 }]} 
          onPress={createPost}
          disabled={postLoading}
        >
          <Text style={styles.navButtonText}>
            {postLoading ? 'Отправка...' : 'Отправить Тестовый POST'}
          </Text>
        </TouchableOpacity>

        {apiError && <Text style={styles.errorText}>Ошибка GET-запроса: {apiError}</Text>}

        {(images && images.length > 0) && (
          <View style={[styles.apiList, { borderTopColor: isDarkMode ? '#444' : '#eee' }]}>
            <Text style={[styles.listHeader, { color: isDarkMode ? '#aaa' : '#333' }]}>Список загруженных картинок ({images.length} шт.):</Text>
            {images.slice(0, 4).map(renderImage)}
          </View>
        )}
      </View>

      {/* Секция Локальные данные */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Локальные данные (useState)</Text>
        <TouchableOpacity style={[styles.button, styles.localButton]} onPress={addLocalItem}>
          <Text style={styles.navButtonText}>Добавить локальный элемент</Text>
        </TouchableOpacity>

        <View style={styles.localList}>
          {localData.length === 0 ? (
            <Text style={[styles.emptyList, { color: isDarkMode ? '#999' : '#999' }]}>Список пуст. Добавьте элемент.</Text>
          ) : (
            localData.slice(0, 5).map(renderLocalItem)
          )}
        </View>
      </View>

      {/* Секция Навигация */}
      <View style={themeStyles.section}>
        <Text style={themeStyles.sectionTitle}>Навигация</Text>
        <View style={styles.navRow}>
          <NavigationButton 
            screen="Media" 
            title="Мультимедиа" 
            icon="camera-outline" 
            color="#34C759" 
          />
          <NavigationButton 
            screen="Gallery" 
            title="Галерея" 
            icon="images-outline" 
            color="#FF9500" 
          />
        </View>
        <View style={styles.navRow}>
          <NavigationButton 
            screen="Analytics" 
            title="Аналитика" 
            icon="stats-chart-outline" 
            color="#5856D6" 
          />
          <NavigationButton 
            screen="Settings" 
            title="Настройки" 
            icon="settings-outline" 
            color="#FF3B30" 
          />
        </View>
      </View>

    </ScrollView>
  );
};

// 🚀 Функция для динамических стилей
const getStyles = (isDarkMode) => StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: isDarkMode ? '#121212' : '#f5f5f5',
    padding: 10,
  },
  section: {
    backgroundColor: isDarkMode ? '#1e1e1e' : 'white',
    padding: 15,
    borderRadius: 10,
    marginBottom: 15,
    shadowColor: isDarkMode ? '#000' : '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: isDarkMode ? 0.3 : 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 15,
    color: isDarkMode ? '#eee' : '#333',
  },
  counter: {
    fontSize: 24,
    textAlign: 'center',
    marginBottom: 15,
    color: isDarkMode ? '#fff' : '#1c1c1e',
  },
});

// 🚀 Статические стили
const styles = StyleSheet.create({
  buttonRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 5,
  },
  button: {
    paddingHorizontal: 20,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    marginVertical: 5,
    flex: 1,
    marginHorizontal: 5,
    backgroundColor: '#007AFF',
  },
  resetButton: {
    backgroundColor: '#FF3B30',
  },
  apiButton: {
    backgroundColor: '#007AFF',
  },
  postButton: {
    backgroundColor: '#34C759',
  },
  localButton: {
    backgroundColor: '#5856D6',
    marginBottom: 15,
  },
  navButton: {
    paddingHorizontal: 10,
    paddingVertical: 15,
    borderRadius: 8,
    alignItems: 'center',
    flex: 1,
    marginHorizontal: 5,
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 10,
